print('n missing closed7 | median time mean time restricted mean | median effort mean effort mean handoff reopen rate | total recorded minutes')
for ks in [('workflow',),('service_group','workflow'),('severity','workflow'),('intake_channel','workflow'),('severity','service_group','workflow'),('date','workflow')]:
 for k,v in groups(I,ks).items(): print(k,out(v))
print('missing',[(i['incident_id'],i['date'],i['service_group'],i['severity'],i['intake_channel']) for i in I if i['missing']])
print('late',[(i['incident_id'],i['time']) for i in I if i['time'] and i['time']>10080])
for keys in [('severity',),('severity','service_group'),('severity','service_group','intake_channel')]:
 print('adjust',keys)
 gs=groups(I,keys)
 for k,rr in gs.items():
  w=groups(rr,['workflow'])
  print(k,*[(p,len(v),sum(i['missing'] for i in v),round(agg(v,'responder_minutes'),1)) for (p,),v in w.items()])
 for target in ['assist','manual','pooled']:
  diff={}
  for metric in ['time','restricted','closed7','responder_minutes','handoffs','reopened_within_72h']:
   st=[(len(rr) if target=='pooled' else sum(i['workflow']==target for i in rr),agg([i for i in rr if i['workflow']=='assist'],metric),agg([i for i in rr if i['workflow']=='manual'],metric)) for rr in gs.values()]
   diff[metric]=tuple(round(sum(w*x for w,a,m in st for x in [a if j==0 else m if j==1 else a-m])/sum(w for w,a,m in st),4) for j in range(3))
  print(target,diff)
for wk in [S[:14],S[14:]]:
 print('staffing',[(k,sum(int(i[k]) for i in wk)) for k in ('scheduled_responder_hours','interruption_minutes','incidents_opened')])
